/* SQL Quest service worker (generated by scripts/build-sw.mjs). */
const VERSION = "__VERSION__";
const PRECACHE = __PRECACHE__;
const STATIC_CACHE = `sqlq-static-${VERSION}`;
const PAGES_CACHE = "sqlq-pages";
const RUNTIME_CACHE = "sqlq-runtime";

self.addEventListener("install", (event) => {
	event.waitUntil(
		(async () => {
			const cache = await caches.open(STATIC_CACHE);
			// One by one so a single failure does not abort the whole install.
			await Promise.all(
				PRECACHE.map((url) =>
					cache.add(new Request(url, { cache: "reload" })).catch((e) => {
						console.warn("[sw] precache failed", url, e);
					}),
				),
			);
			await self.skipWaiting();
		})(),
	);
});

self.addEventListener("activate", (event) => {
	event.waitUntil(
		(async () => {
			for (const key of await caches.keys()) {
				if (key.startsWith("sqlq-static-") && key !== STATIC_CACHE) await caches.delete(key);
			}
			await self.clients.claim();
		})(),
	);
});

async function networkFirstPage(request) {
	const cache = await caches.open(PAGES_CACHE);
	try {
		const ctrl = new AbortController();
		const timer = setTimeout(() => ctrl.abort(), 4000);
		const res = await fetch(request, { signal: ctrl.signal });
		clearTimeout(timer);
		if (res.ok) cache.put(request, res.clone());
		return res;
	} catch {
		return (
			(await cache.match(request)) ||
			(await caches.match("/", { ignoreSearch: true })) ||
			new Response("Offline", { status: 503, headers: { "content-type": "text/plain" } })
		);
	}
}

async function cacheFirst(request) {
	const hit = await caches.match(request, { ignoreSearch: false });
	if (hit) return hit;
	const res = await fetch(request);
	if (res.ok) (await caches.open(RUNTIME_CACHE)).put(request, res.clone());
	return res;
}

async function staleWhileRevalidate(request) {
	const cache = await caches.open(RUNTIME_CACHE);
	const hit = await caches.match(request);
	const fresh = fetch(request)
		.then((res) => {
			if (res.ok) cache.put(request, res.clone());
			return res;
		})
		.catch(() => hit);
	return hit || fresh;
}

self.addEventListener("fetch", (event) => {
	const { request } = event;
	if (request.method !== "GET") return;
	const url = new URL(request.url);
	if (url.origin !== self.location.origin) return;
	// Server functions and APIs: always live (the client queues sync offline).
	if (url.pathname.startsWith("/_serverFn") || url.pathname.startsWith("/api/")) return;
	if (request.mode === "navigate") {
		event.respondWith(networkFirstPage(request));
		return;
	}
	if (url.pathname.startsWith("/assets/")) {
		event.respondWith(cacheFirst(request));
		return;
	}
	event.respondWith(staleWhileRevalidate(request));
});
